//! Bundled library of original procedural characters.
//!
//! The catalog is data only. It is generated by
//! `scripts/generate_avatar_catalog.py`, committed as JSON, embedded at compile
//! time, and validated before first use.

use std::{
    collections::{BTreeSet, HashMap},
    sync::OnceLock,
};

use serde::{Deserialize, Serialize};
use thiserror::Error;

use crate::spec::{CharacterSpec, SpecError};

pub const CATALOG_SCHEMA_VERSION: u32 = 1;
/// Namespace every bundled character id must use.
pub const CATALOG_NAMESPACE: &str = "miyora";
/// Character selected when the user has not chosen one yet.
pub const DEFAULT_AVATAR_ID: &str = "miyora.aoi";

const BUNDLED_CATALOG_JSON: &str = include_str!("../catalog/characters.json");

#[derive(Debug, Clone, Error, PartialEq)]
pub enum CatalogError {
    #[error("catalog JSON is invalid: {0}")]
    Json(String),
    #[error("unsupported catalog schema version {0}")]
    UnsupportedSchema(u32),
    #[error("catalog character `{id}` is invalid: {reason}")]
    Character { id: String, reason: String },
    #[error("catalog contains duplicate character id `{0}`")]
    DuplicateId(String),
    #[error("catalog character `{0}` is outside the `miyora` namespace")]
    Namespace(String),
    #[error("catalog metadata field `{0}` is required")]
    MissingMetadata(&'static str),
    #[error("catalog does not contain the default character `{0}`")]
    MissingDefault(&'static str),
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct AvatarCatalog {
    pub schema_version: u32,
    pub creator: String,
    pub license: String,
    pub source: String,
    pub characters: Vec<CharacterSpec>,
    #[serde(skip)]
    index: HashMap<String, usize>,
}

impl AvatarCatalog {
    /// Returns the validated catalog compiled into this binary.
    pub fn bundled() -> Result<&'static AvatarCatalog, CatalogError> {
        static CATALOG: OnceLock<Result<AvatarCatalog, CatalogError>> = OnceLock::new();
        CATALOG
            .get_or_init(|| AvatarCatalog::parse(BUNDLED_CATALOG_JSON.as_bytes()))
            .as_ref()
            .map_err(Clone::clone)
    }

    pub fn parse(bytes: &[u8]) -> Result<Self, CatalogError> {
        let mut catalog: Self =
            serde_json::from_slice(bytes).map_err(|error| CatalogError::Json(error.to_string()))?;
        if catalog.schema_version != CATALOG_SCHEMA_VERSION {
            return Err(CatalogError::UnsupportedSchema(catalog.schema_version));
        }
        for (field, value) in [
            ("creator", &catalog.creator),
            ("license", &catalog.license),
            ("source", &catalog.source),
        ] {
            if value.trim().is_empty() {
                return Err(CatalogError::MissingMetadata(field));
            }
        }
        let mut seen = BTreeSet::new();
        for (position, character) in catalog.characters.iter().enumerate() {
            character
                .validate()
                .map_err(|error: SpecError| CatalogError::Character {
                    id: character.id.clone(),
                    reason: error.to_string(),
                })?;
            if !character
                .id
                .strip_prefix(CATALOG_NAMESPACE)
                .is_some_and(|rest| rest.starts_with('.'))
            {
                return Err(CatalogError::Namespace(character.id.clone()));
            }
            if !seen.insert(character.id.clone()) {
                return Err(CatalogError::DuplicateId(character.id.clone()));
            }
            catalog.index.insert(character.id.clone(), position);
        }
        if !catalog.index.contains_key(DEFAULT_AVATAR_ID) {
            return Err(CatalogError::MissingDefault(DEFAULT_AVATAR_ID));
        }
        Ok(catalog)
    }

    pub fn get(&self, id: &str) -> Option<&CharacterSpec> {
        self.index
            .get(id)
            .map(|&position| &self.characters[position])
    }

    pub fn contains(&self, id: &str) -> bool {
        self.index.contains_key(id)
    }

    pub fn default_character(&self) -> &CharacterSpec {
        // `parse` guarantees the default id is present.
        &self.characters[self.index[DEFAULT_AVATAR_ID]]
    }
}

#[cfg(test)]
mod tests {
    use std::collections::HashSet;

    use super::*;
    use crate::spec::{sample_spec, BodyType};

    #[test]
    fn bundled_catalog_has_at_least_one_hundred_valid_unique_characters() {
        let catalog = AvatarCatalog::bundled().expect("bundled catalog validates");
        assert!(
            catalog.characters.len() >= 100,
            "catalog has {} characters",
            catalog.characters.len()
        );
        let names: HashSet<_> = catalog.characters.iter().map(|c| c.name.as_str()).collect();
        assert_eq!(names.len(), catalog.characters.len(), "names are unique");
        assert_eq!(catalog.default_character().id, DEFAULT_AVATAR_ID);
    }

    #[test]
    fn bundled_catalog_covers_every_body_type() {
        let catalog = AvatarCatalog::bundled().expect("bundled catalog validates");
        for body in [
            BodyType::Humanoid,
            BodyType::Beast,
            BodyType::Robot,
            BodyType::Slime,
            BodyType::Bird,
        ] {
            assert!(
                catalog.characters.iter().any(|c| c.body == body),
                "missing body {body:?}"
            );
        }
    }

    fn catalog_json(characters: Vec<CharacterSpec>) -> Vec<u8> {
        serde_json::to_vec(&serde_json::json!({
            "schemaVersion": 1,
            "creator": "Test",
            "license": "CC0-1.0",
            "source": "unit test",
            "characters": characters,
        }))
        .expect("serialize")
    }

    #[test]
    fn rejects_duplicates_foreign_namespaces_and_missing_default() {
        let mut default = sample_spec();
        default.id = DEFAULT_AVATAR_ID.into();
        let duplicate = default.clone();
        assert_eq!(
            AvatarCatalog::parse(&catalog_json(vec![default.clone(), duplicate])).unwrap_err(),
            CatalogError::DuplicateId(DEFAULT_AVATAR_ID.into())
        );

        let mut foreign = sample_spec();
        foreign.id = "other.pet".into();
        assert!(matches!(
            AvatarCatalog::parse(&catalog_json(vec![default.clone(), foreign])),
            Err(CatalogError::Namespace(_))
        ));

        assert!(matches!(
            AvatarCatalog::parse(&catalog_json(vec![sample_spec()])),
            Err(CatalogError::MissingDefault(_))
        ));

        let catalog = AvatarCatalog::parse(&catalog_json(vec![default])).expect("valid");
        assert!(catalog.contains(DEFAULT_AVATAR_ID));
        assert!(catalog.get("miyora.unknown").is_none());
    }
}
